function reviewQuestion(a,i,r,all=false){const e=exam(),done=!OMR.pending(a)||(a.state==='blank'&&r.blankReviewed),sel=OMR.effective(a),ls=letters(e);return `<div class="review-question"><div class="review-q-top"><strong>Q${i+1} <span class="pill ${done?'green':'amber'}">${a.state==='multiple'?'Multiple marks':a.state==='blank'?'Blank':a.state==='faint'?'Faint / uncertain':'Single answer'}${done?' · reviewed':''}</span></strong><span class="review-progress">Key ${ls[e.key[i]]||'—'}</span></div>${!all?`<img class="review-crop" data-q="${i}" alt="Cropped scan of question ${i+1}">`:''}<div class="review-options">${ls.map((l,j)=>`<button class="choice ${sel===j?'selected':a.detected.includes(j)?'detected':''}" aria-label="Set question ${i+1} to ${l}" data-action="resolveChoice" data-q="${i}" data-choice="${j}">${l}</button>`).join('')}<span>${a.detected.length?'Read: '+a.detected.map(j=>ls[j]).join(', '):'No mark read'}</span><button class="text-link" data-action="resolveIncorrect" data-q="${i}">${a.credit===0?'✓ No credit':'No credit'}</button><button class="text-link" data-action="resetAnswer" data-q="${i}">Reset</button></div>${a.state==='blank'&&r.blankReviewed&&a.resolved==null&&a.credit==null?'<p style="font-size:10px;margin:8px 0 0">Included in the confirmed blank group total.</p>':''}</div>`;}
async function imageFrom(src){return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Photo could not be opened.'));img.src=src;});}
function reviewResult(){return currentResult(currentReview);}
function reReview(){const r=reviewResult();if(r!==testResult){r.updatedAt=new Date().toISOString();persist();}const id=currentReview;render();openReview(id);}
async function exportGrades(){if(!keyReady()){toast('Complete the answer key before exporting grades.');switchView('key');return;}const e=exam();if(!e.students.length){toast('Add students before exporting.');return;}const max=e.key.length*e.points,header=['Serial','Student ID','Name','Lab','Lecture','Attendance','Score','Maximum','Percentage','Status','Pending answers','Blank group credits','Scan time','Instructor','Last updated'];function rows(ss){return[header,...ss.map(s=>{const r=e.results.find(r=>r.studentId===s.id),sc=r?score(r):null;return[s.serial,s.studentId,s.name,s.lab,s.lecture||'',s.absent?'Absent':'Present',sc?sc.score:'',max,sc?Math.round(sc.score/max*10000)/100:'',s.absent?'Absent':!r?'Not scanned':sc.pending?'Provisional':'Complete',sc?sc.pending:'',r?.blankReviewed?r.blankCredit:0,r?.at||'',r?.instructor||'',r?.updatedAt||r?.at||''];})];}const tables=[{name:'All grades',rows:rows(sorted(e))}];const used=new Set(['All grades','Answer details','Quiz info']);for(const lab of [...new Set(sorted(e).map(s=>s.lab||'Unassigned'))]){let name=lab.replace(/[\[\]:*?/\\]/g,'_').slice(0,28)||'Lab',base=name,i=1;while(used.has(name))name=base.slice(0,25)+' '+i++;used.add(name);tables.push({name,rows:rows(sorted(e).filter(s=>(s.lab||'Unassigned')===lab))});}tables.push({name:'Answer details',rows:[['Serial','Student ID','Name','Question','Key','Detected','Reviewed answer','Decision','Correct','Fill ratios'],...e.results.flatMap(r=>{const s=e.students.find(s=>s.id===r.studentId);return r.answers.map((a,i)=>{let v=OMR.effective(a),group=a.state==='blank'&&r.blankReviewed&&a.resolved==null&&a.credit==null;return[s?.serial,s?.studentId,s?.name,i+1,letters(e)[e.key[i]]||'',a.detected.map(i=>letters(e)[i]).join(', '),v==null?'':letters(e)[v],group?'Blank group: '+r.blankCredit+' total credits':OMR.pending(a)?'Pending':a.credit!=null?'Manual no credit':a.resolved!=null?'Reviewed':'Automatic',group||OMR.pending(a)?'':a.credit!=null?a.credit:v===e.key[i]?1:0,a.ratios.map(v=>Math.round(v*100)+'%').join(' / ')];});})]});tables.push({name:'Quiz info',rows:[['Field','Value'],['Quiz',e.name],['Date',e.date],['Lab / course',e.lab],['Answer sheet',e.template.name],['Questions',e.key.length],['Points per question',e.points],['Exported',new Date().toISOString()],['Provisional scores','Unresolved answers currently receive 0 points. Check Status and Pending answers before finalizing.'],['Blank group credits','Credits are added to the paper total without assigning correctness to specific blank questions.'],['Student matching','Papers assigned by present-student serial order; no automatic ID OCR.']]});await Sheets.write(tables,safeName(e.name)+'_Grades');toast(e.results.some(r=>score(r).pending)?'Grade workbook ready. Provisional scores are clearly flagged.':'Grade workbook ready to download.');}
async function rosterTemplate(){await Sheets.write([{name:'Students',rows:[['Serial','Student ID','Name','Lab','Lecture'],[1,'20260001','Student name','Lab 1','Lecture 1'],[2,'20260002','Another student','Lab 1','Lecture 1']]}],'BubbleGrade_Roster_Template');}
function studentModal(id){const e=exam(),s=e.students.find(s=>s.id===id)||{id:'',serial:Math.max(0,...e.students.map(s=>Number(s.serial)||0))+1,studentId:'',name:'',lab:e.lab};openModal(s.id?'Edit student':'Add a student',`<form id="studentForm" data-id="${s.id}"><div class="form-grid"><label class="field">Serial<input name="serial" required value="${esc(s.serial)}"></label><label class="field">Student ID<input name="studentId" value="${esc(s.studentId)}"></label><label class="field full-span">Name<input name="name" required value="${esc(s.name)}"></label><label class="field">Lab<input name="lab" value="${esc(s.lab)}"></label><label class="field">Lecture<input name="lecture" value="${esc(s.lecture)}"></label></div></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="studentForm">Save student</button>`);}
function detectHeader(rows){let best=0,rank=-1;rows.slice(0,30).forEach((r,i)=>{let c=r.map(x=>String(x).toLowerCase().trim()),score=c.filter(x=>/^(serial|serial no\.?|no\.?|s\.?n\.?|id|student id|student.?name|name|lab|group|الاسم|الرقم|كود الطالب|اسم الطالب|مسلسل|السكشن|المعمل)$/.test(x)).length;if(score>rank){rank=score;best=i;}});return best;}
function importRosterModal(data){importData=data;const first=data.find(x=>x.rows.length);if(!first)throw Error('No rows found in this workbook.');let hi=detectHeader(first.rows),headers=first.rows[hi].map(String);importData.header=hi;importData.headers=headers;function sel(name,regex,allow=false){let guess=headers.findIndex(h=>regex.test(h.toLowerCase().trim()));return `<label class="field">${name}<select name="${name}">${allow?'<option value="-1">Not provided</option>':''}${headers.map((h,i)=>`<option value="${i}" ${i===guess?'selected':''}>${esc(h||'Column '+(i+1))}</option>`).join('')}</select></label>`;}
openModal('Match your roster columns',`<p>All nonempty sheets are read. Matching student IDs are updated; scanned results are preserved. Missing serials are assigned in import order. Check the preview before importing.</p><form id="importForm"><div class="form-grid">${sel('Serial',/serial|مسلسل|^no\.?$/,true)}${sel('ID',/^(id|student id|student_id|كود الطالب)$/i,true)}${sel('Name',/name|اسم|الاسم/)}${sel('Lab',/lab|group|section|سكشن|معمل/,true)}${sel('Lecture',/lecture|محاضر/,true)}</div></form><div class="import-preview table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${first.rows.slice(hi+1,hi+6).map(r=>`<tr>${headers.map((_,j)=>`<td>${esc(r[j])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="alert" style="margin-top:15px;margin-bottom:0">Serials control scan order. Student IDs should be unique; duplicate serials will be flagged before import.</div>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="importForm">Import students</button>`);}
function applyRoster(form){const e=exam(),f=new FormData(form),idx={serial:+f.get('Serial'),studentId:+f.get('ID'),name:+f.get('Name'),lab:+f.get('Lab'),lecture:+f.get('Lecture')};const cols=Object.values(idx).filter(x=>x>=0);if(new Set(cols).size!==cols.length){toast('Choose a different column for each field.');return;}let incoming=[],seenIds=new Set(),skip=0;for(const sh of importData){let hi=detectHeader(sh.rows);for(const row of sh.rows.slice(hi+1)){if(!row[idx.name]?.toString().trim())continue;const studentId=idx.studentId>=0?String(row[idx.studentId]??'').trim():'',name=String(row[idx.name]).trim(),serial=idx.serial>=0?String(row[idx.serial]??'').trim():'';if(studentId&&seenIds.has(studentId)){skip++;continue;}if(studentId)seenIds.add(studentId);incoming.push({studentId,name,serial:serial||String(incoming.length+1),lab:idx.lab>=0?String(row[idx.lab]||sh.name):sh.name,lecture:idx.lecture>=0?String(row[idx.lecture]||''):''});}}
if(!incoming.length){toast('No student rows matched. Check the selected Name column.');return;}const cloned=e.students.map(s=>({...s}));for(const s of incoming){const old=cloned.find(x=>s.studentId?x.studentId===s.studentId:!x.studentId&&x.name===s.name&&x.lab===s.lab);if(old)Object.assign(old,s);else cloned.push({...s,id:uid(),absent:false});}const serials=cloned.map(s=>s.serial);if(new Set(serials).size!==serials.length){toast('Duplicate serials found. Make serials unique across all labs before importing.');return;}e.students=cloned;persist();closeModal();render();toast(`${incoming.length} student rows imported${skip?' · '+skip+' duplicate IDs skipped':''}.`);}
async function beginCalibration(file){const c=await loadImage(file,1600);const found=findPoints(c);cal={canvas:c,markers:found||[],blocks:[],phase:found?'blocks':'markers',clicks:[],autoDetected:!!found};showCalibration();}
function showCalibration(){const t=cal;openModal('Calibrate your blank sheet',`<div class="step-list"><span class="${t.phase==='markers'?'active':''}">1 · Reference marks</span><span class="${t.phase==='blocks'?'active':''}">2 · Bubble blocks</span><span>3 · Check & save</span></div><div class="alert" id="calInstruction">${t.phase==='markers'?`Tap reference ${t.markers.length+1}: ${['top-left','top-right','bottom-right','bottom-left'][t.markers.length]}. Use the centers of the four printed registration marks, clockwise. A straight, blank digital sheet works best.`:(t.autoDetected?'Four square registration marks were detected and highlighted. Check their centers. ':'')+'For each block, enter its first question and row count. Tap the center of the FIRST option in the FIRST row, then the LAST option in the LAST row. Verify the overlaid rings.'}</div><div class="calibration-tools"><div class="calibration-grid"><label class="field">First question<input id="calStart" type="number" value="${t.blocks.reduce((n,b)=>n+b.rows,0)+1}" min="1" max="100"></label><label class="field">Rows in block<input id="calRows" type="number" value="10" min="1" max="100"></label><label class="field">Choices<select id="calOptions">${[2,3,4,5].map(n=>`<option ${n===(t.options||5)?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Bubble radius (px)<input id="calRadius" type="number" value="${t.radius||Math.max(5,Math.round(t.canvas.width/80))}" min="2" max="50"></label></div><p id="blockStatus" style="margin:9px 0 0;font-size:10px">${t.phase==='blocks'?'Tap first bubble. '+t.blocks.length+' blocks mapped.':'Reference points: '+t.markers.length+' / 4'}</p></div><div class="scan-image-wrap"><canvas id="calCanvas"></canvas></div><label class="field">Template name<input id="calName" value="${esc(t.name||'Custom ZipGrade sheet')}"></label>`,`<button class="btn small" data-action="calUndo">Undo</button><button class="btn small" data-action="calReset">Restart</button><button class="btn primary" data-action="calSave" ${t.blocks.length?'':'disabled'}>Save layout</button>`);cal=t;const cv=$('#calCanvas');cv.width=t.canvas.width;cv.height=t.canvas.height;drawCalibration();cv.onclick=ev=>calClick(canvasPoint(ev,cv));}
function drawCalibration(){const cv=$('#calCanvas'),ctx=cv.getContext('2d');ctx.drawImage(cal.canvas,0,0);drawDots(ctx,cal.markers);cal.blocks.forEach(b=>{const [a,z]=b.points;for(let r=0;r<b.rows;r++)for(let j=0;j<b.options;j++){let x=a[0]+(z[0]-a[0])*j/(b.options-1),y=a[1]+(z[1]-a[1])*(b.rows===1?0:r/(b.rows-1));ctx.beginPath();ctx.arc(x,y,b.radius,0,Math.PI*2);ctx.strokeStyle='#26a16f';ctx.lineWidth=2;ctx.stroke();if(j===0){ctx.font='bold 12px Arial';ctx.fillStyle='#1f7b4f';ctx.textAlign='right';ctx.fillText(b.start+r,x-b.radius-5,y+4);}}});drawDots(ctx,cal.clicks);}
function calClick(p){if(cal.phase==='markers'){cal.markers.push(p);if(cal.markers.length===4){try{OMR.homography(cal.markers,[[0,0],[800,0],[800,1100],[0,1100]]);}catch(err){cal.markers.pop();toast(err.message);return;}cal.phase='blocks';}cal.name=$('#calName').value;showCalibration();return;}
let start=+$('#calStart').value,rows=+$('#calRows').value,options=+$('#calOptions').value,radius=+$('#calRadius').value;if(!Number.isInteger(start)||!Number.isInteger(rows)||rows<1||start<1||start+rows-1>100||radius<2||radius>50){toast('Use 1–100 total questions and a radius of 2–50 pixels.');return;}if(cal.blocks.some(b=>b.options!==options)){toast('Use the same number of choices for every block.');return;}if(cal.blocks.some(b=>start<b.start+b.rows&&start+rows>b.start)){toast('Question numbers overlap an existing block.');return;}cal.clicks.push(p);if(cal.clicks.length===2){const[a,z]=cal.clicks;if(z[0]<=a[0]||rows>1&&z[1]<=a[1]){cal.clicks=[];toast('Last bubble must be to the right and, for multiple rows, below the first.');drawCalibration();return;}cal.blocks.push({start,rows,options,radius,points:cal.clicks});cal.clicks=[];cal.radius=radius;cal.options=options;cal.name=$('#calName').value;showCalibration();}else{$('#blockStatus').textContent='Now tap the LAST choice in the LAST row of this block.';drawCalibration();}}
function saveCalibration(){if(!cal?.blocks.length||cal.clicks.length){toast('Finish the current bubble block first.');return;}const e=exam(),questions=[];for(const b of cal.blocks){for(let r=0;r<b.rows;r++){const[a,z]=b.points;questions[b.start-1+r]={bubbles:Array.from({length:b.options},(_,j)=>[a[0]+(z[0]-a[0])*j/(b.options-1),a[1]+(z[1]-a[1])*(b.rows===1?0:r/(b.rows-1))]),r:b.radius};}}for(let i=0;i<questions.length;i++){if(!questions[i]){toast(`Question ${i+1} has not been mapped.`);return;}}e.template={name:$('#calName').value.trim()||'Custom sheet',w:cal.canvas.width,h:cal.canvas.height,options:cal.options,questions,markers:cal.markers,background:cal.canvas.toDataURL('image/jpeg',.85),native:false};const blankRead=OMR.analyze(cal.canvas.getContext('2d',{willReadFrequently:true}).getImageData(0,0,cal.canvas.width,cal.canvas.height),e.template,cal.markers,e.threshold);e.template.questions.forEach((q,i)=>q.baseline=blankRead.answers[i].ratios);e.key=Array.from({length:questions.length},(_,i)=>e.key[i]!=null&&e.key[i]<cal.options?e.key[i]:null);persist();closeModal();render();toast('Custom layout saved. Scan a known paper to check calibration.');}
function settings(){const e=exam();openModal('Quiz settings',`<form id="settingsForm"><div class="form-grid"><label class="field full-span">Quiz name<input name="name" value="${esc(e.name)}" required maxlength="100"></label><label class="field full-span">Instructor name<input name="instructor" value="${esc(state.instructor)}" maxlength="100"></label><label class="field">Course / lab<input name="lab" value="${esc(e.lab)}"></label><label class="field">Date<input name="date" type="date" value="${e.date}"></label><label class="field full-span">Bubble fill threshold: <span id="thresholdValue">${Math.round(e.threshold*100)}%</span><input type="range" name="threshold" id="threshold" value="${e.threshold}" min="0.15" max="0.65" step="0.01"></label></div><p>Lower thresholds detect lighter marks; higher thresholds require more fill. This applies to future scans. Existing scans keep their detected answers unless you re-read their photo.</p><div class="btn-row settings-actions"><button class="btn small" type="button" data-action="backup">Back up all quizzes</button><button class="btn small" type="button" data-action="newExam">New quiz</button><button class="btn small danger" type="button" data-action="deleteExam">Delete this quiz</button></div></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="settingsForm">Save settings</button>`);}
function help(){openModal('A calmer way through the stack',`<ol class="help-steps"><li><strong>Choose a sheet.</strong> Print a BubbleGrade layout, or upload a blank standard / custom ZipGrade sheet and calibrate its marks and bubble blocks.</li><li><strong>Set the answer key.</strong> Choose one correct answer per question, or paste A B C D…</li><li><strong>Add students.</strong> Import Excel / CSV, mark absences, and arrange papers in serial order. Handwritten student IDs are not read automatically.</li><li><strong>Start the full-screen camera.</strong> On your phone, open this HTTPS link in Chrome or Safari and allow the rear camera. Keep the page upright and include all four square marks. Student information stays over the camera. Align the printed squares with all four targets and hold steady; this accepts the displayed student without a confirmation tap. Change the student by serial or ID before positioning the paper. Remove each paper fully before the next. Upload photos if camera access is blocked.</li><li><strong>Review the flags.</strong> For multiple marks, select the student’s intended answer. For blanks, select an answer or award a count of credits for the group. Faint marks also need review. Switch between reviewing each paper and reviewing the batch.</li><li><strong>Export Excel.</strong> Get all students, a sheet per lab, detailed answer decisions, and clear provisional / complete status.</li></ol><div class="alert">This is a first working version. Calibrate and test a few known papers in your actual lighting before using it for official marks. Inspect the scanned-paper overlay when a detection looks wrong.</div><h3>Groups, rescans and other instructors</h3><p>Starting a scan opens the group and mode selector. Choose all students, a lab or a lecture. Check the displayed name, serial and ID before positioning each paper. The full-screen camera scans automatically when the four corner targets match and the paper stays steady. Find a specific student by serial / ID to replace a saved score; the previous score is kept until the new scan succeeds. Anonymous validation never saves the test score or photo.</p><p>Use Share quiz / merge scans to share a quiz setup and import colleagues’ results. Instructors can also create independent quizzes. This works on GitHub Pages without a database. Sharing uses downloaded files; automatic live synchronization is not included.</p><p>Data and images are stored only in this browser, on this device. Clearing browser data removes them. Use <strong>Back up workspace</strong> to transfer or keep a copy. Quizzes do not sync across devices.</p><p>ZipGrade is a trademark of its owner. BubbleGrade is an independent tool. A ZipGrade custom-form code alone is not enough: the printed layout must be calibrated here.</p><p><a href="JSZip-LICENSE.txt" target="_blank" rel="noopener">JSZip license</a> · <a href="PDFjs-LICENSE.txt" target="_blank" rel="noopener">PDF.js license</a></p>`,`<button class="btn" data-action="demo">Try the sample scan</button><button class="btn primary" data-action="close">Got it</button>`);}
async function backup(){toast('Preparing workspace backup…');const photos={};for(const e of state.exams)for(const r of e.results){if(r.imgId){const p=await photoGet(r.imgId);if(p)photos[r.imgId]=p;}}download(new Blob([JSON.stringify({format:'bubblegrade-workspace',version:1,state,photos})],{type:'application/json'}),'BubbleGrade_Backup_'+new Date().toISOString().slice(0,10)+'.json');toast('Backup ready to download, including available paper photos.');}
function validTemplate(t){if(!t||!Number.isFinite(t.w)||!Number.isFinite(t.h)||t.w<50||t.h<50||t.w>10000||t.h>10000||!Number.isInteger(t.options)||t.options<2||t.options>5||!Array.isArray(t.markers)||t.markers.length!==4||!Array.isArray(t.questions)||t.questions.length<1||t.questions.length>100)return false;const pt=p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>=0&&p[0]<=t.w&&p[1]>=0&&p[1]<=t.h;return t.markers.every(pt)&&t.questions.every(q=>Number.isFinite(q.r)&&q.r>=1&&q.r<=100&&q.bubbles?.length===t.options&&q.bubbles.every(pt)&&(!q.baseline||Array.isArray(q.baseline)&&q.baseline.length===t.options&&q.baseline.every(v=>Number.isFinite(v)&&v>=0&&v<=1)))&&(!t.background||/^data:image\/(png|jpeg);base64,/.test(t.background));}
function validState(s){return s?.version===1&&Array.isArray(s.exams)&&s.exams.length>0&&s.exams.length<=200&&s.exams.every(e=>typeof e.id==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(e.id)&&typeof e.name==='string'&&validTemplate(e.template)&&Array.isArray(e.key)&&e.key.length===e.template.questions.length&&e.key.every(k=>k===null||Number.isInteger(k)&&k>=0&&k<e.template.options)&&Number.isFinite(e.points)&&e.points>0&&Array.isArray(e.students)&&e.students.every(st=>typeof st.id==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(st.id)&&typeof st.name==='string')&&Array.isArray(e.results)&&e.results.every(r=>typeof r.id==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(r.id)&&e.students.some(s=>s.id===r.studentId)&&Array.isArray(r.points)&&r.points.length===4&&r.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))&&Array.isArray(r.answers)&&r.answers.length===e.key.length&&r.answers.every(a=>['blank','multiple','faint','single'].includes(a.state)&&Array.isArray(a.detected)&&a.detected.every(n=>Number.isInteger(n)&&n>=0&&n<e.template.options)&&Array.isArray(a.ratios)&&a.ratios.length===e.template.options&&a.ratios.every(Number.isFinite)&&(a.resolved==null||Number.isInteger(a.resolved)&&a.resolved>=0&&a.resolved<e.template.options)&&(a.credit==null||a.credit===0||a.credit===1))));}
async function restoreFile(f){const b=JSON.parse(await f.text());if(b.format!=='bubblegrade-workspace'||!validState(b.state))throw Error('This is not a valid BubbleGrade workspace backup.');openModal('Restore this backup?',`<p>This backup contains ${b.state.exams.length} quizzes and ${b.state.exams.reduce((n,e)=>n+e.results.length,0)} scans. Restoring replaces the workspace in this browser. Download a backup of the current workspace first if you want to keep it.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="confirmRestore">Restore workspace</button>`);window.pendingRestore=b;}
async function demo(){stopCamera();closeModal();let e=state.exams.find(e=>e.isDemo);if(!e){e=makeExam('Sample quiz');e.isDemo=true;e.lab='Demo lab';e.key=e.key.map((_,i)=>i%5);e.students=Array.from({length:5},(_,i)=>({id:uid(),name:'Demo student '+(i+1),serial:String(i+1),studentId:'DEMO00'+(i+1),lab:'Demo lab',absent:i===3}));state.exams.push(e);}state.active=e.id;view='scan';location.hash='scan';persist();render();if(e.results.length){await openReview(e.results[0].id);return;}const marks=e.key.map(k=>[k]);marks[2]=[0,2];marks[7]=[1,3];marks[5]=[];marks[13]=[];const svg=OMR.svg(e.template,e.name,marks),img=await imageFrom('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)),c=document.createElement('canvas');c.width=800;c.height=1132;c.getContext('2d').drawImage(img,0,0);const p=findPoints(c);if(!p)throw Error('Sample registration marks could not be read.');e.scanGroup={type:'all',value:''};session={active:true,mode:'queue',confirmed:Gradebook.next(e)?.id,studentId:null,source:'upload'};await processCapture(c,p);await openReview(e.results[0].id);toast('Sample generated and read by the real scanning engine.');}
function newExam(){stopCamera();openModal('A fresh stack',`<form id="newExamForm"><label class="field">Quiz name<input name="name" required maxlength="100" placeholder="e.g. Medicinal Plants · Quiz 1" autofocus></label><p>A new quiz starts with a 20-question sheet. You can customize it before scanning.</p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="newExamForm">Create quiz</button>`);}
const actions={
 goScan:()=>switchView('scan'),goKey:()=>switchView('key'),goStudents:()=>switchView('students'),goResults:()=>switchView('results'),settings,help,backup,demo,newExam,
 close:()=>{const wasAlign=!!align;closeModal();if(wasAlign)uploadQueue=[];},
 startCamera:()=>scanSession('camera'),stopCamera:()=>{stopCamera();render();},capture:()=>{if(needsRemoval&&exam().continuous){toast('Remove the previous paper from view before the next capture.');return;}return capture();},uploadScan:()=>scanSession('upload'),
 keyChoice:b=>{exam().key[+b.dataset.q]=+b.dataset.choice;persist();render();},
 clearKey:()=>{openModal('Clear the answer key?',`<p>All ${exam().key.length} correct answers will be cleared. Existing scores are recalculated from the key.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn danger" data-action="confirmClearKey">Clear key</button>`);},
 confirmClearKey:()=>{exam().key.fill(null);persist();closeModal();render();},
 pasteKey:()=>openModal('Paste your answer key',`<form id="pasteKeyForm"><label class="field">${exam().key.length} letters, A–${letters(exam()).at(-1)}<textarea name="key" rows="5" placeholder="A B C D E A B C D E…" required></textarea></label><p>Separate letters with spaces, commas or new lines, or use a continuous string such as ABCDE.</p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="pasteKeyForm">Apply answer key</button>`),
 importRoster:()=>$('#rosterInput').click(),rosterTemplate,exportRoster:()=>Sheets.write([{name:'Students',rows:[['Serial','Student ID','Name','Lab','Lecture'],...sorted(exam()).map(s=>[s.serial,s.studentId,s.name,s.lab,s.lecture||''])]}],safeName(exam().name)+'_Roster'),
 addStudent:()=>studentModal(),editStudent:b=>studentModal(b.dataset.id),deleteStudent:b=>{const s=exam().students.find(s=>s.id===b.dataset.id);if(!s||resultFor(s))return;exam().students=exam().students.filter(x=>x.id!==s.id);persist();render();},
 absentNext:()=>{const n=nextStudent();if(n){n.absent=true;exam().cursor=null;persist();render();}},
 pickStudent:()=>scanSession(stream?'live':'configure','student'),
 createTemplate:()=>{if(exam().results.length)return;let n=+$('#nativeQuestions').value,o=+$('#nativeOptions').value;if(!Number.isInteger(n)||n<1||n>100){toast('Choose 1–100 questions.');return;}exam().template=OMR.template(n,o);exam().key=Array.from({length:n},(_,i)=>exam().key[i]!=null&&exam().key[i]<o?exam().key[i]:null);persist();render();toast('Layout saved. Check your answer key before scanning.');},
 printSheet:()=>{let area=$('#printArea');if(!area){area=document.createElement('div');area.id='printArea';area.hidden=false;area.style.display='none';document.body.append(area);}area.innerHTML=OMR.svg(exam().template,exam().name);window.print();},
 downloadSheet:async()=>{const e=exam(),img=await imageFrom('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(OMR.svg(e.template,e.name))),c=document.createElement('canvas');c.width=1600;c.height=2264;c.getContext('2d').drawImage(img,0,0,1600,2264);c.toBlob(b=>download(b,safeName(e.name)+'_Blank_Sheet.png'));},
 exportTemplate:()=>download(new Blob([JSON.stringify({format:'bubblegrade-template',version:1,template:exam().template})],{type:'application/json'}),safeName(exam().template.name)+'.json'),
 importTemplate:()=>{const i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=async()=>{try{const d=JSON.parse(await i.files[0].text());if(d.format!=='bubblegrade-template'||!validTemplate(d.template))throw Error('Invalid template file.');const e=exam();e.template=d.template;e.key=Array.from({length:e.template.questions.length},(_,i)=>e.key[i]!=null&&e.key[i]<e.template.options?e.key[i]:null);persist();render();toast('Template imported.');}catch(err){toast(err.message);}};i.click();},
 calibrate:()=>{if(!exam().results.length)$('#templateInput').click();},
 calUndo:()=>{if(cal.clicks.length)cal.clicks=[];else if(cal.blocks.length)cal.blocks.pop();else if(cal.markers.length){cal.markers.pop();cal.phase='markers';}showCalibration();},
 calReset:()=>{cal.markers=[];cal.blocks=[];cal.clicks=[];cal.phase='markers';showCalibration();},calSave:saveCalibration,
 alignReset:()=>{align.points=[];drawAlign();},alignDone:async()=>{const a=align;if(a.points.length!==4)return;closeModal();await processCapture(a.canvas,a.points);if(exam().reviewMode==='end')await nextUpload();},
 review:b=>openReview(b.dataset.id),reviewNext:()=>{const r=exam().results.find(r=>score(r).pending);if(r)openReview(r.id);else toast('No papers are waiting for review.');},
 resolveChoice:b=>{const r=reviewResult(),a=r.answers[+b.dataset.q];a.resolved=+b.dataset.choice;a.credit=null;if(a.state==='blank'){r.blankReviewed=false;r.blankCredit=0;}reReview();},
 resolveIncorrect:b=>{const r=reviewResult(),a=r.answers[+b.dataset.q];a.credit=0;a.resolved=null;if(a.state==='blank'){r.blankReviewed=false;r.blankCredit=0;}reReview();},
 resetAnswer:b=>{const r=reviewResult(),a=r.answers[+b.dataset.q];a.credit=null;a.resolved=null;if(a.state==='blank'){r.blankReviewed=false;r.blankCredit=0;}reReview();},
 applyBlank:()=>{const r=reviewResult();r.blankCredit=+$('#blankCount').value;r.blankReviewed=true;reReview();},resetBlank:()=>{const r=reviewResult();r.blankReviewed=false;r.blankCredit=0;reReview();},
 reviewClose:async()=>{closeModal();render();await nextUpload();},reviewDone:async()=>{const r=reviewResult();if(score(r).pending){const next=exam().results.find(x=>x.id!==r.id&&score(x).pending);if(next){await openReview(next.id);return;}toast('Some answers are still pending. Resolve them or choose Keep pending.');return;}closeModal();render();if(uploadQueue.length){await nextUpload();return;}const next=exam().results.find(x=>score(x).pending);if(next)await openReview(next.id);},
 reanalyze:()=>{const r=reviewResult();openModal('Re-read this photo?',`<form id="reanalyzeForm" data-id="${r.id}"><label class="field">New fill threshold<input name="threshold" type="number" value="${exam().threshold}" min="0.15" max="0.65" step="0.01" required></label><p>All manual decisions for this paper will be reset. The original photo and reference points are used again.</p></form>`,`<button class="btn" data-action="cancelReanalyze" data-id="${r.id}">Cancel</button><button class="btn primary" type="submit" form="reanalyzeForm">Re-read photo</button>`);},cancelReanalyze:b=>openReview(b.dataset.id),
 rescan:b=>{const r=exam().results.find(r=>r.id===b.dataset.id);scanSession(stream?'live':'configure','student',r.studentId);},
 export:exportGrades,restore:()=>$('#restoreInput').click(),confirmRestore:async()=>{const b=window.pendingRestore;if(!b)return;stopCamera();try{for(const [id,p]of Object.entries(b.photos||{}))if(typeof p==='string'&&/^data:image\/(jpeg|png);base64,/.test(p))await photoPut(id,p);state=b.state;migrate();session.active=false;session.confirmed=null;state.active=state.exams.some(e=>e.id===state.active)?state.active:state.exams[0].id;persist();closeModal();window.pendingRestore=null;switchView('scan');toast('Workspace restored.');}catch(err){toast('Restore failed: '+err.message);}},
 deleteExam:()=>openModal('Delete this quiz?',`<p>This permanently removes <strong>${esc(exam().name)}</strong>, its roster, scans and decisions from this browser. Download a workspace backup first if you need it.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn danger" data-action="confirmDeleteExam">Delete quiz</button>`),
 confirmDeleteExam:()=>{stopCamera();const e=exam();e.results.forEach(r=>photoDelete(r.imgId));state.exams=state.exams.filter(x=>x.id!==e.id);if(!state.exams.length)state.exams=[makeExam()];state.active=state.exams[0].id;session.active=false;session.confirmed=null;persist();closeModal();switchView('scan');}
};
document.addEventListener('click',async ev=>{const nav=ev.target.closest('[data-view]');if(nav){ev.preventDefault();switchView(nav.dataset.view);return;}const b=ev.target.closest('[data-action]');if(b&&!b.disabled){try{const f=actions[b.dataset.action];if(f)await f(b);}catch(err){toast(err.message||'Something went wrong. Please try again.');console.error(err);}}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,d=new FormData(f),e=exam();try{if(f.id==='studentForm'){const serial=String(d.get('serial')).trim(),name=String(d.get('name')).trim(),studentId=String(d.get('studentId')).trim(),lab=String(d.get('lab')).trim(),lecture=String(d.get('lecture')||'').trim();if(!serial||!name)throw Error('Enter a serial and name.');if(e.students.some(s=>s.id!==f.dataset.id&&(s.serial===serial||studentId&&s.studentId===studentId)))throw Error('This serial or student ID is already in the roster.');const old=e.students.find(s=>s.id===f.dataset.id);if(old)Object.assign(old,{serial,name,studentId,lab,lecture});else e.students.push({id:uid(),serial,name,studentId,lab,lecture,absent:false});persist();closeModal();render();}
 else if(f.id==='settingsForm'){state.instructor=String(d.get('instructor')||'').trim();e.name=String(d.get('name')).trim();e.lab=String(d.get('lab')).trim();e.date=String(d.get('date'));e.threshold=+d.get('threshold');persist();closeModal();render();}
 else if(f.id==='newExamForm'){const name=String(d.get('name')).trim();if(!name)return;const n=makeExam(name);n.sharedId=n.id;n.scanGroup={type:'all',value:''};state.exams.push(n);state.active=n.id;session.active=false;session.confirmed=null;persist();closeModal();switchView('sheet');}
 else if(f.id==='pasteKeyForm'){const text=String(d.get('key')).toUpperCase().replace(/[\s,;|]+/g,'');if(text.length!==e.key.length||[...text].some(l=>!letters(e).includes(l)))throw Error(`Enter exactly ${e.key.length} letters from A to ${letters(e).at(-1)}.`);e.key=[...text].map(c=>c.charCodeAt(0)-65);persist();closeModal();render();toast('Answer key applied.');}
 else if(f.id==='scanSessionForm'){await applyScanSession(f);}
 else if(f.id==='importForm')applyRoster(f);
 else if(f.id==='reanalyzeForm'){const r=currentResult(f.dataset.id),src=r===testResult?testPhoto:await photoGet(r.imgId);if(!src)throw Error('Original photo is unavailable. Rescan the paper instead.');const img=await imageFrom(src),c=document.createElement('canvas');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);const threshold=+d.get('threshold');r.answers=OMR.analyze(c.getContext('2d').getImageData(0,0,c.width,c.height),e.template,r.points,threshold).answers;r.blankCredit=0;r.blankReviewed=false;r.threshold=threshold;if(r!==testResult){r.updatedAt=new Date().toISOString();persist();}render();await openReview(r.id);}
}catch(err){toast(err.message);}});
document.addEventListener('change',ev=>{const x=ev.target,e=exam();if(x.id==='examSelect'){stopCamera();state.active=x.value;session={active:false,mode:'queue',studentId:null,confirmed:null,source:'camera'};persist();closeModal();render();}else if(x.id==='continuous'){e.continuous=x.checked;persist();}else if(x.id==='reviewMode'){e.reviewMode=x.value;persist();}else if(x.id==='points'){let v=+x.value;if(v>0&&v<=1000){e.points=v;persist();render();}else{toast('Points must be above 0 and at most 1000.');x.value=e.points;}}else if(x.id==='quickTemplate'&&x.value!=='current'&&!e.results.length){e.template=OMR.template(+x.value);e.key=Array(e.template.questions.length).fill(null);persist();render();}else if(x.dataset.absent){const s=e.students.find(s=>s.id===x.dataset.absent);if(s&&!resultFor(s)){s.absent=x.checked;persist();render();}}});
document.addEventListener('input',ev=>{if(ev.target.id==='threshold')$('#thresholdValue').textContent=Math.round(ev.target.value*100)+'%';if(['studentSearch','resultSearch'].includes(ev.target.id)){const pos=ev.target.selectionStart,id=ev.target.id;query=ev.target.value;render();const el=$('#'+id);el.focus();el.setSelectionRange(pos,pos);}});
$('#imageInput').onchange=async ev=>{uploadQueue=[...ev.target.files];ev.target.value='';await nextUpload();};
$('#templateInput').onchange=async ev=>{try{if(ev.target.files[0])await beginCalibration(ev.target.files[0]);}catch(err){toast(err.message);}ev.target.value='';};
$('#rosterInput').onchange=async ev=>{try{if(ev.target.files[0]){toast('Reading workbook…');importRosterModal(await Sheets.read(ev.target.files[0]));}}catch(err){toast(err.message);}ev.target.value='';};
$('#restoreInput').onchange=async ev=>{try{if(ev.target.files[0])await restoreFile(ev.target.files[0]);}catch(err){toast(err.message);}ev.target.value='';};
$('#modal').addEventListener('cancel',ev=>{ev.preventDefault();if(align)uploadQueue=[];closeModal();});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['scan','key','students','sheet','results'].includes(v)&&v!==view){if(v!=='scan')stopCamera();view=v;render();}});
window.addEventListener('pagehide',()=>{stopCamera();});
persist();render();
